export const spotsFor = (part: BadgerPartId, spots: readonly BadgerSpot[] = LEFT_SPOTS): readonly BadgerSpot[] =>
	spots.filter((s) => s.part === part);

/**
 * HEAD markings (front head controls facial markings and which ear is dark).
 * H-EAR-L-CAP: the dark cap is the whole outer flap of the ANATOMICAL LEFT ear (screen right in the front
 *   head; the near ear in left-facing views; the far ear in right-facing views). It is implemented as that
 *   ear's fill colour in every head view (see parts/heads), not as a path.
 * The remaining H- markings are spots; `paths` gives the path per head view in that view's head-local space
 * (views where the marking is hidden are absent).
 */
export type HeadMarking = {
	readonly id: string;
	readonly side: 'left' | 'right';
	readonly desc: string;
	readonly paths: Partial<Record<string, string>>;
};

